property.value:
let $mapTypes := ('Map', 'HashMap', 'LinkedHashMap', 'TreeMap', 'SortedMap', 'NavigableMap', 'ConcurrentMap',
                  'ConcurrentHashMap', 'AbstractMap'),
    $valueCollectors := ('toMap', 'toUnmodifiableMap', 'toConcurrentMap'),
    $groupings := ('groupingBy', 'groupingByConcurrent'),
    $passThrough := ('stream', 'parallelStream', 'filter', 'sorted', 'peek', 'distinct', 'limit', 'skip',
                     'takeWhile', 'dropWhile', 'parallel', 'sequential', 'unordered'),
    $nullable := ('Nullable', 'CheckForNull'),
    $nullableMethods := function($node) {
      $node/ancestor::CompilationUnit//MethodDeclaration[ModifierList/Annotation[@SimpleName = $nullable]]/@Name
      | $node/ancestor::CompilationUnit//RecordComponent[ModifierList/Annotation[@SimpleName = $nullable]]/VariableId/@Name
    },
    $nullableValueType := function($type) {
      exists($type[self::ClassType[@SimpleName = $mapTypes]]
        [empty(TypeArguments) or TypeArguments/*[2][self::WildcardType or Annotation[@SimpleName = $nullable]
                                                    or self::ClassType[@SimpleName = 'Object']]])
    },
    $declarations := function($access) {
      let $name := $access/@Name
      return $access/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression]//VariableId[@Name = $name]
             | $access/ancestor::ClassBody/FieldDeclaration/VariableDeclarator/VariableId[@Name = $name]
             | $access/ancestor::RecordDeclaration/RecordComponentList/RecordComponent/VariableId[@Name = $name]
    },
    $typesOf := function($variables) {
      $variables/(parent::FormalParameter | parent::VariableDeclarator/parent::*| parent::RecordComponent)/ClassType
    },
    $declaredTypes := function($access) {
      $typesOf($declarations($access))
      | $typesOf(for $alias in $declarations($access)/parent::VariableDeclarator/*[2][self::VariableAccess]
                 return $declarations($alias))
    },
    $nullableMap := function($source) {
      exists($source[pmd-java:typeIs('java.util.Properties')])
      or (some $type in (
            if ($source[self::VariableAccess or self::FieldAccess]) then $declaredTypes($source)
            else if ($source[self::MethodCall])
              then $source/ancestor::CompilationUnit//MethodDeclaration[@Name = $source/@MethodName]/ClassType
            else ()) satisfies $nullableValueType($type))
      or exists($source[self::MethodCall][@MethodName = ('readValue', 'convertValue', 'fromJson')]
                [pmd-java:typeIs('java.util.Map')])
    },
    $entryValue := function($function) {
      exists($function[self::MethodReference[@MethodName = 'getValue'][TypeExpression/ClassType[@SimpleName = 'Entry']]
        | self::LambdaExpression[*[last()]/(self::CastExpression/*[last()] | self::*)
            [self::MethodCall[@MethodName = 'getValue'][ArgumentList/@Size = 0][*[1][self::VariableAccess]]]]])
    },
    $identityMap := function($step) {
      exists($step[@MethodName = 'map']/ArgumentList/LambdaExpression
        [*[last()][self::VariableAccess][@Name = ../LambdaParameterList/LambdaParameter/VariableId/@Name]])
    },
    $nullEntries := function($call) {
      some $collect in $call/parent::ArgumentList/parent::MethodCall[@MethodName = 'collect'] satisfies
        (some $entries in $collect/*[1]/descendant-or-self::MethodCall[@MethodName = 'entrySet'][ArgumentList/@Size = 0]
         satisfies
           (let $steps := $entries/ancestor::* intersect $collect/descendant::*
            return
              (every $step in $steps satisfies
                ($step is $step/../*[1]
                 and $step[self::MethodCall][@MethodName = $passThrough or $identityMap(.)]))
              and empty($steps[self::MethodCall][@MethodName = 'filter']
                         [.//MethodCall[@MethodName = 'getValue']
                          and (.//NullLiteral or .//InstanceofExpression
                               or .//MethodCall[@MethodName = ('nonNull', 'isNull')])])
              and $nullableMap($entries/*[1])))
    },
    $nullResult := function($result, $function) {
      exists($result[self::NullLiteral
        | self::ConditionalExpression[*[2][self::NullLiteral] or *[3][self::NullLiteral]]
        | self::MethodCall[@MethodName = 'orElse'][ArgumentList/*[1][self::NullLiteral]]
        | self::MethodCall[@MethodName = 'get'][ArgumentList/@Size = 1][*[1][pmd-java:typeIs('java.util.Map')]]
        | self::MethodCall[@MethodName = $nullableMethods($function)]])
    },
    $nullFunction := function($function) {
      exists($function[self::MethodReference]
               [@MethodName = $nullableMethods(.)
                or @MethodName = 'get' and *[1][self::VariableAccess or self::FieldAccess][pmd-java:typeIs('java.util.Map')]])
      or (some $result in ($function[self::LambdaExpression]/*[last()][not(self::Block)]
                           | $function[self::LambdaExpression]/Block//ReturnStatement/*[1])
          satisfies $nullResult($result, $function))
    },
    $shapeOf := function($expression, $parameters) {
      string-join($expression/descendant-or-self::*/(@MethodName | @Name | self::*[self::StringLiteral or self::NumericLiteral]/@Image)
                  ! (if (local-name(.) = 'Name' and . = $parameters) then '#' else string(.)), '.')
    },
    $testedShapes := function($filter) {
      let $lambda := $filter/ArgumentList/LambdaExpression,
          $parameters := $lambda/LambdaParameterList//VariableId/@Name,
          $body := $lambda/*[last()][not(self::Block)]
      return $body/descendant-or-self::*[self::InfixExpression[@Operator = '!='][NullLiteral]
                                         or self::MethodCall[@MethodName = 'nonNull']]
               [. is $body or ($body/self::InfixExpression[@Operator = '&&']
                               and empty(ancestor::*[ancestor::*[. is $body]][not(self::InfixExpression[@Operator = '&&'])]))]
             /(self::InfixExpression/*[not(self::NullLiteral)] | self::MethodCall/ArgumentList/*[1])
             ! $shapeOf(., $parameters)
    },
    $valueShape := function($function) {
      if ($function/self::MethodReference) then concat($function/@MethodName, '.#')
      else $shapeOf($function/self::LambdaExpression/*[last()][self::MethodCall],
                    $function/LambdaParameterList//VariableId/@Name)
    },
    $filteredBefore := function($call, $function) {
      let $shape := $valueShape($function)
      return exists($shape) and $shape != '' and
        (some $collect in $call/parent::ArgumentList/parent::MethodCall[@MethodName = 'collect'] satisfies
          (some $filter in $collect/*[1]/descendant-or-self::MethodCall[@MethodName = 'filter'] satisfies
            $shape = $testedShapes($filter)
            and (every $step in $filter/ancestor::* intersect $collect/descendant::* satisfies
                  ($step is $step/../*[1] and $step[self::MethodCall][@MethodName = $passThrough]))))
    },
    $reaches := function($call, $function) {
      ($nullFunction($function) or ($entryValue($function) and $nullEntries($call)))
      and not($filteredBefore($call, $function))
    },
    $helpers := //MethodDeclaration[.//MethodCall[@MethodName = $valueCollectors]
                  [pmd-java:typeIs('java.util.stream.Collector')]/ArgumentList/*[2][self::VariableAccess]]
return (
  //MethodCall[@MethodName = $valueCollectors][pmd-java:typeIs('java.util.stream.Collector')]
    [$reaches(., ArgumentList/*[2])]
  | //MethodCall[@MethodName = $groupings][pmd-java:typeIs('java.util.stream.Collector')]
    [$reaches(., ArgumentList/*[1])]
  | //MethodCall[some $helper in $helpers satisfies (@MethodName = $helper/@Name
      and (some $forwarded in $helper//MethodCall[@MethodName = $valueCollectors]
             [pmd-java:typeIs('java.util.stream.Collector')]/ArgumentList/*[2][self::VariableAccess]/@Name
           satisfies (let $index := count($helper/FormalParameters/FormalParameter[VariableId/@Name = $forwarded]
                                          /preceding-sibling::FormalParameter) + 1
                      return $reaches(., ArgumentList/*[$index]))))]
)
